#!/usr/bin/env node
"use strict";

import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import { fileURLToPath } from "node:url";

const cliName = "open" + "code";

export function resolveConfigDir(explicitDir) {
  if (explicitDir) {
    if (explicitDir === "~") return os.homedir();
    if (explicitDir.startsWith("~/") || explicitDir.startsWith("~\\")) {
      return path.join(os.homedir(), explicitDir.slice(2));
    }
    return path.resolve(explicitDir);
  }
  if (process.env.OPENCODE_CONFIG_DIR) return path.resolve(process.env.OPENCODE_CONFIG_DIR);
  if (process.env.XDG_CONFIG_HOME) return path.join(process.env.XDG_CONFIG_HOME, cliName);
  return path.join(os.homedir(), ".config", cliName);
}

function findPluginsArraySpan(raw) {
  const pluginsMatch = /"plugins"\s*:\s*\[/.exec(raw);
  if (!pluginsMatch) return null;
  const openBracketIdx = pluginsMatch.index + pluginsMatch[0].length - 1;
  let depth = 0;
  let inString = false;
  let escape = false;
  let inLineComment = false;
  let inBlockComment = false;

  for (let i = openBracketIdx; i < raw.length; i++) {
    const ch = raw[i];
    const next = raw[i + 1];

    if (inLineComment) {
      if (ch === "\n") inLineComment = false;
      continue;
    }
    if (inBlockComment) {
      if (ch === "*" && next === "/") {
        inBlockComment = false;
        i++;
      }
      continue;
    }
    if (escape) {
      escape = false;
      continue;
    }
    if (inString) {
      if (ch === "\\") escape = true;
      else if (ch === '"') inString = false;
      continue;
    }
    if (ch === "/" && next === "/") {
      inLineComment = true;
      i++;
      continue;
    }
    if (ch === "/" && next === "*") {
      inBlockComment = true;
      i++;
      continue;
    }
    if (ch === '"') {
      inString = true;
      continue;
    }
    if (ch === "[") depth++;
    else if (ch === "]") {
      depth--;
      if (depth === 0) {
        return { openBracketIdx, closeBracketIdx: i };
      }
    }
  }
  return null;
}

function findLastCodeCharIndex(str) {
  let inString = false;
  let escape = false;
  let inLineComment = false;
  let inBlockComment = false;
  let lastCodeIdx = -1;

  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    const next = str[i + 1];

    if (inLineComment) {
      if (ch === "\n") inLineComment = false;
      continue;
    }
    if (inBlockComment) {
      if (ch === "*" && next === "/") {
        inBlockComment = false;
        i++;
      }
      continue;
    }
    if (escape) {
      escape = false;
      lastCodeIdx = i;
      continue;
    }
    if (inString) {
      if (ch === "\\") escape = true;
      else if (ch === '"') inString = false;
      lastCodeIdx = i;
      continue;
    }
    if (ch === "/" && next === "/") {
      inLineComment = true;
      i++;
      continue;
    }
    if (ch === "/" && next === "*") {
      inBlockComment = true;
      i++;
      continue;
    }
    if (ch === '"') {
      inString = true;
      lastCodeIdx = i;
      continue;
    }
    if (!/\s/.test(ch)) {
      lastCodeIdx = i;
    }
  }
  return lastCodeIdx;
}

function addPluginToJsoncFile(filePath, defaultSchema, pluginEntryStr, matchSubstr) {
  if (!fs.existsSync(filePath)) {
    const initial =
      "{\n" +
      '  "$schema": "' +
      defaultSchema +
      '",\n' +
      '  "plugins": [\n' +
      "    " +
      pluginEntryStr +
      "\n" +
      "  ]\n" +
      "}\n";
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, initial, "utf8");
    return "created";
  }

  const raw = fs.readFileSync(filePath, "utf8");
  if (raw.includes(matchSubstr)) {
    return "already-present";
  }

  const span = findPluginsArraySpan(raw);
  if (span) {
    const { openBracketIdx, closeBracketIdx } = span;
    const insideRaw = raw.slice(openBracketIdx + 1, closeBracketIdx);
    const lastCodeIdx = findLastCodeCharIndex(insideRaw);
    if (lastCodeIdx === -1) {
      const updated =
        raw.slice(0, openBracketIdx + 1) +
        "\n    " +
        pluginEntryStr +
        "\n  " +
        raw.slice(closeBracketIdx);
      fs.writeFileSync(filePath, updated, "utf8");
      return "updated";
    }
    const lastChar = insideRaw[lastCodeIdx];
    const withComma =
      lastChar === ","
        ? insideRaw.replace(/\s+$/, "")
        : insideRaw.slice(0, lastCodeIdx + 1) + "," + insideRaw.slice(lastCodeIdx + 1).replace(/\s+$/, "");
    const updated =
      raw.slice(0, openBracketIdx + 1) +
      withComma +
      "\n    " +
      pluginEntryStr +
      "\n  " +
      raw.slice(closeBracketIdx);
    fs.writeFileSync(filePath, updated, "utf8");
    return "updated";
  }

  const lastBraceIdx = raw.lastIndexOf("}");
  if (lastBraceIdx !== -1) {
    const beforeRaw = raw.slice(0, lastBraceIdx);
    const lastCodeIdx = findLastCodeCharIndex(beforeRaw);
    const lastChar = lastCodeIdx !== -1 ? beforeRaw[lastCodeIdx] : "{";
    const needsComma = lastChar !== "{" && lastChar !== ",";
    const withComma = needsComma
      ? beforeRaw.slice(0, lastCodeIdx + 1) + "," + beforeRaw.slice(lastCodeIdx + 1).replace(/\s+$/, "")
      : beforeRaw.replace(/\s+$/, "");
    const updated =
      withComma +
      '\n  "plugins": [\n    ' +
      pluginEntryStr +
      "\n  ]\n}\n";
    fs.writeFileSync(filePath, updated, "utf8");
    return "updated";
  }

  return "skipped";
}

export async function installPlugin(options) {
  const opts = options || {};
  const configDir = resolveConfigDir(opts.configDir);
  fs.mkdirSync(configDir, { recursive: true });

  const pkgName = "@nandoblanco/opencode-local-tokens";
  const matchKey = "opencode-local-tokens";
  const entryStr = opts.cacheAlerts === true
    ? JSON.stringify({ package: pkgName, options: { cacheAlerts: true } })
    : JSON.stringify(pkgName);

  const jsoncCandidate = path.join(configDir, cliName + ".jsonc");
  const jsonCandidate = path.join(configDir, cliName + ".json");
  const serverConfigFile = fs.existsSync(jsoncCandidate)
    ? jsoncCandidate
    : fs.existsSync(jsonCandidate)
      ? jsonCandidate
      : jsoncCandidate;

  const serverStatus = addPluginToJsoncFile(
    serverConfigFile,
    "https://" + cliName + ".ai/config.json",
    entryStr,
    matchKey
  );

  return {
    configDir,
    serverConfigFile,
    serverStatus,
  };
}

const isDirectRun =
  process.argv[1] && path.resolve(process.argv[1]) === path.resolve(fileURLToPath(import.meta.url));
if (isDirectRun) {
  const args = process.argv.slice(2);
  const cmd = args[0];

  if (args.includes("--help") || args.includes("-h")) {
    console.log(
      "opencode-tokens install [--dir <config-dir>] [--cache-alerts]\n" +
      "opencode-tokens [query] [--project name] [--model name] [--tag tag] [--liked] [--limit count] [--sort mode]\n" +
      "Sort: billed, total, steps, updated, newest, oldest, title, relevance\n" +
      "Commands: install, like <session>, unlike <session>, tag <session> <tags>, untag <session> <tags>, note <session> <text>\n" +
      "Tags: comma-separated, e.g. review,billing\n" +
      "In OpenCode: /tokens opens analytics (Ctrl+S sort, Ctrl+T add tags, Ctrl+R remove tags); /handoff creates a checkpoint for a fresh session."
    );
  } else if (cmd === "install" || cmd === "init" || cmd === "setup") {
    let configDir;
    let cacheAlerts = false;
    for (let i = 1; i < args.length; i++) {
      if ((args[i] === "--dir" || args[i] === "-d") && args[i + 1]) {
        configDir = args[i + 1];
        i++;
      } else if (args[i] === "--cache-alerts") {
        cacheAlerts = true;
      }
    }
    installPlugin({ configDir, cacheAlerts })
      .then((res) => {
        console.log("opencode-local-tokens installed:");
        console.log("  Config file: " + res.serverConfigFile + " (" + res.serverStatus + ")");
      })
      .catch((err) => {
        console.error("Install failed:", err);
        process.exit(1);
      });
  } else {
    import("./src/tokens.ts")
      .then(({ runTokensCli }) => runTokensCli(args))
      .catch((err) => {
        console.error("Command failed:", err);
        process.exit(1);
      });
  }
}

export * from "./tokens.ts";
export * from "./summary.ts";
export * from "./rpc.ts";
export { default, server, executeTokensQuery, executeMutateSession, executeSessionStatus, executeCreateHandoff } from "./server.ts";

import type { Plugin } from "@opencode/plugin";
import { fetchLocalTokenStats } from "./summary.ts";
import { saveHandoffState, searchHandoffHistory, type HandoffState } from "./handoff.ts";
import { measureHandoff } from "./measurement.ts";
import { prepareHandoff } from "./prepare-handoff.ts";
import {
  parseInlineTokensFilter,
  TokensRpc,
  type UsageCreateHandoffInput,
  type UsageCreateHandoffOutput,
  type UsageMutateSessionInput,
  type UsageMutateSessionOutput,
  type UsageSessionStatusInput,
  type UsageTokensInput,
} from "./rpc.ts";
import {
  analyzeTokens,
  buildSessionHandoff,
  emptyTokens,
  getSessionStepStatus,
  mutateSessionTag,
  type SessionStepStatus,
  type TokensReport,
} from "./tokens.ts";
export async function executeTokensQuery(
  input: UsageTokensInput = {}
): Promise<TokensReport> {
  const parsed =
    typeof input.rawInput === "string"
      ? parseInlineTokensFilter(input.rawInput)
      : {
          query: input.query ?? "",
          project: input.project ?? "",
          model: input.model ?? "",
          tag: input.tag ?? "",
          likedOnly: Boolean(input.likedOnly),
        };

  const limit = input.limit && input.limit > 0 ? input.limit : 80;
  try {
    const report = analyzeTokens({
      query: input.query ?? parsed.query,
      project: input.project ?? parsed.project,
      model: input.model ?? parsed.model,
      tag: input.tag ?? parsed.tag,
      likedOnly: input.likedOnly ?? parsed.likedOnly,
      limit,
    });
    return JSON.parse(JSON.stringify(report)) as TokensReport;
  } catch {
    return {
      totals: {
        ...emptyTokens(),
        sessions: 0,
        turns: 0,
        scopedSessions: 0,
      },
      sortedModels: [],
      sortedProjects: [],
      topTags: [],
      sessions: [],
      totalSessionsMatched: 0,
      filters: {
        query: parsed.query,
        model: parsed.model,
        project: parsed.project,
        tag: parsed.tag,
        likedOnly: parsed.likedOnly,
        limit,
      },
    };
  }
}

export async function executeMutateSession(
  input: UsageMutateSessionInput
): Promise<UsageMutateSessionOutput> {
  try {
    const res = mutateSessionTag(input.action, input.sessionPrefix, input.value);
    return JSON.parse(
      JSON.stringify({
        ok: true,
        sessionId: res.sessionId,
        entry: res.entry,
      })
    ) as UsageMutateSessionOutput;
  } catch (err: any) {
    return {
      ok: false,
      error: err?.message || String(err),
    };
  }
}

export async function executeSessionStatus(
  input: UsageSessionStatusInput = {},
  modelCapacities: Record<string, number> = {}
): Promise<SessionStepStatus | null> {
  try {
    const status = getSessionStepStatus(input.sessionId, {
      warnThreshold: input.warnThreshold,
      limit: input.limit,
      modelCapacities,
    });
    return status ? (JSON.parse(JSON.stringify(status)) as SessionStepStatus) : null;
  } catch {
    return null;
  }
}

export async function executeCreateHandoff(
  input: UsageCreateHandoffInput = {}
): Promise<UsageCreateHandoffOutput> {
  try {
    const handoff = buildSessionHandoff(input.sessionId, {
      note: input.note,
    });
    return JSON.parse(
      JSON.stringify({
        ok: true,
        handoff,
      })
    ) as UsageCreateHandoffOutput;
  } catch (err: any) {
    return {
      ok: false,
      error: err?.message || String(err),
    };
  }
}

function fmtCompactTok(n: number): string {
  if (!n || n <= 0) return "0";
  if (n >= 1e9) return `${(n / 1e9).toFixed(2)}B`;
  if (n >= 1e6) return `${(n / 1e6).toFixed(2)}M`;
  if (n >= 1e3) return `${(n / 1e3).toFixed(1)}K`;
  return String(Math.round(n));
}

export const server: Plugin.Definition = {
  id: "opencode-local-tokens",
  async setup(ctx) {
    await ctx.session.hook("context", event => {
      event.system.push({ type: "text", text: "Before a requested session handoff, save working state with handoff_checkpoint (goal, constraints, decisions, verified evidence, unfinished work, failures, pending requests, nextStep); use handoff_history to search predecessor sessions. These tools do not authorize an automatic handoff." });
    });
    await ctx.tool.transform(editor => {
      editor.add({
        name: "handoff_checkpoint",
        description: "Save concise working state before a session handoff. Include decision reasons, evidence, unfinished work, failed approaches, pending user requests, and exact next action. No new session or automatic handoff is triggered.",
        input: {
          type: "object",
          properties: {
            goal: { type: "string" }, nextStep: { type: "string" },
            ...Object.fromEntries(["constraints", "decisions", "verified", "unfinished", "failures", "pendingUserRequests"].map(key => [key, { type: "array", items: { type: "string" } }])),
          },
          required: ["goal", "nextStep", "constraints", "decisions", "verified", "unfinished", "failures", "pendingUserRequests"],
          additionalProperties: false,
        },
        async execute(input, context) {
          const saved = saveHandoffState(context.sessionID, input as HandoffState);
          return { content: `Working state saved for ${context.sessionID} at ${saved.savedAt}. The handoff button will include it. Refresh it if the task changes.` };
        },
      });
      editor.add({
        name: "handoff_history",
        description: "Search a previous OpenCode session and its explicitly linked predecessors. Literal phrase search returns bounded, paginated evidence including tool results and message IDs. Does not search unrelated sessions or invoke a model.",
        input: { type: "object", properties: { sessionId: { type: "string" }, query: { type: "string" }, offset: { type: "integer", minimum: 0 } }, required: ["sessionId", "query"], additionalProperties: false },
        async execute(input) {
          return { content: JSON.stringify(searchHandoffHistory(input as { sessionId: string; query: string; offset?: number })) };
        },
      });
    });
    const measurements = new AbortController();
    if (ctx.event) void (async () => {
      try {
        for await (const event of ctx.event.subscribe({ types: ["session.idle"], signal: measurements.signal })) {
          measureHandoff(event.data.sessionID, "idle");
        }
      } catch (error) {
        if (!measurements.signal.aborted) console.warn("[opencode-local-tokens] Measurement subscription unavailable.");
      }
    })();

    if (ctx?.rpc?.register) {
      await ctx.rpc.register(TokensRpc, {
        async summary() {
          return fetchLocalTokenStats();
        },
        async tokens(input) {
          return executeTokensQuery(input);
        },
        async mutateSession(input) {
          return executeMutateSession(input);
        },
        async sessionStatus(input) {
          const status = await executeSessionStatus(input);
          if (!status) return null;
          try {
            const models = await ctx.model.list({ location: { directory: status.directory } });
            const capacities = Object.fromEntries(models.data.map(model => [`${model.providerID}/${model.id}`, model.limit.context]));
            return executeSessionStatus(input, capacities);
          } catch {
            return status;
          }
        },
        async createHandoff(input) {
          const status = getSessionStepStatus(input.sessionId);
          if (!status) return { ok: false, error: "No active session found to prepare a handoff." };
          try {
            await prepareHandoff(status.sessionId, ctx.session);
          } catch (error) {
            return { ok: false, error: error instanceof Error ? error.message : String(error) };
          }
          return executeCreateHandoff({ ...input, sessionId: status.sessionId });
        },
      });
    }

    return () => measurements.abort();
  },
};

export default server;
